runtime.baseCss:
:root {
  --c-bg: #192b1b;
  --c-bg-alt: #1e3221;
  --c-bg-light: #e8e4d6;
  --c-bg-light-alt: #dedad0;
  --c-fg: #d4cfbf;
  --c-fg-2: rgba(212, 207, 191, 0.6);
  --c-fg-3: rgba(212, 207, 191, 0.32);
  --c-fg-light: #192b1b;
  --c-fg-light-2: rgba(25, 43, 27, 0.58);
  --c-fg-light-3: rgba(25, 43, 27, 0.33);
  --c-accent: #c8524a;
  --c-border: rgba(212, 207, 191, 0.12);
  --c-border-light: rgba(25, 43, 27, 0.14);
  --f-display: "Playfair Display", "Noto Serif SC", Georgia, serif;
  --f-heading: "Playfair Display", "Noto Serif SC", Georgia, serif;
  --f-body: "Jost", "Noto Sans SC", system-ui, sans-serif;
  --f-mono: "JetBrains Mono", monospace;
  --sz-display: 10vw;
  --sz-h1: 5.5vw;
  --sz-h2: 3.2vw;
  --sz-h3: 2vw;
  --sz-lead: 1.45vw;
  --sz-body: 1.05vw;
  --sz-caption: 0.82vw;
  --sz-label: 0.7vw;
  --pad-x: 8vw;
  --pad-y: 6.5vh;
  --gap-lg: 4.5vh;
  --gap-md: 2.8vh;
  --gap-sm: 1.4vh;
  --ease-slide: cubic-bezier(0.77, 0, 0.175, 1);
  --dur-slide: 0.9s;
  --ease-enter: cubic-bezier(0.16, 1, 0.3, 1);
  --dur-enter: 0.7s;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--c-bg);
  -webkit-font-smoothing: antialiased;
}

#deck {
  display: flex;
  height: 100vh;
  transition: transform var(--dur-slide) var(--ease-slide);
  will-change: transform;
}

.slide {
  flex: 0 0 100vw;
  width: 100vw;
  height: 100vh;
  position: relative;
  padding: var(--pad-y) var(--pad-x);
  display: grid;
  grid-template-rows: auto 1fr auto;
  overflow: hidden;
}

.slide-body { min-height: 0; }
.slide.dark { background: var(--c-bg); color: var(--c-fg); }
.slide.light { background: var(--c-bg-light); color: var(--c-fg-light); }

[data-anim] { opacity: 0; }

.slide.is-active [data-anim] {
  animation-duration: var(--dur-enter);
  animation-timing-function: var(--ease-enter);
  animation-fill-mode: forwards;
}

.slide.is-active [data-anim="fade-up"] { animation-name: kFadeUp; }
.slide.is-active [data-anim="fade-in"] { animation-name: kFadeIn; }
.slide.is-active [data-anim="reveal-right"] { animation-name: kRevealRight; }
.slide.is-active [data-anim="reveal-left"] { animation-name: kRevealLeft; }
.slide.is-active [data-anim="scale-in"] { animation-name: kScaleIn; }

[data-delay="0"] { animation-delay: 0s; }
[data-delay="1"] { animation-delay: 0.08s; }
[data-delay="2"] { animation-delay: 0.18s; }
[data-delay="3"] { animation-delay: 0.3s; }
[data-delay="4"] { animation-delay: 0.44s; }
[data-delay="5"] { animation-delay: 0.6s; }
[data-delay="6"] { animation-delay: 0.78s; }

@keyframes kFadeUp {
  from { opacity: 0; transform: translateY(28px); }
  to { opacity: 1; transform: none; }
}

@keyframes kFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes kRevealRight {
  from { clip-path: inset(0 100% 0 0); opacity: 1; }
  to { clip-path: inset(0 0% 0 0); opacity: 1; }
}

@keyframes kRevealLeft {
  from { clip-path: inset(0 0 0 100%); opacity: 1; }
  to { clip-path: inset(0 0 0 0%); opacity: 1; }
}

@keyframes kScaleIn {
  from { opacity: 0; transform: scale(0.94); }
  to { opacity: 1; transform: none; }
}

#nav-dots {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 7px;
  z-index: 100;
}

.nav-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  border: none;
  background: rgba(255, 255, 255, 0.22);
  cursor: pointer;
  transition: background 0.3s, transform 0.3s;
  padding: 0;
}

.nav-dot.is-active {
  background: rgba(255, 255, 255, 0.8);
  transform: scale(1.4);
}

#slide-counter { display: none; }

.display {
  font-family: var(--f-display);
  font-size: var(--sz-display);
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.01em;
}

.h1 {
  font-family: var(--f-heading);
  font-size: var(--sz-h1);
  font-weight: 400;
  line-height: 1.1;
}

.h2 {
  font-family: var(--f-heading);
  font-size: var(--sz-h2);
  font-weight: 400;
  line-height: 1.2;
}

.h3 {
  font-family: var(--f-heading);
  font-size: var(--sz-h3);
  font-weight: 400;
  line-height: 1.3;
}

.h1 em, .h2 em, .h3 em {
  font-style: italic;
  color: var(--c-accent);
}

.lead {
  font-family: var(--f-body);
  font-size: var(--sz-lead);
  font-weight: 300;
  line-height: 1.65;
}

.body {
  font-family: var(--f-body);
  font-size: var(--sz-body);
  font-weight: 300;
  line-height: 1.75;
}

.caption {
  font-family: var(--f-body);
  font-size: var(--sz-caption);
  font-weight: 300;
  line-height: 1.55;
}

.label {
  font-family: var(--f-mono);
  font-size: var(--sz-label);
  font-weight: 300;
  letter-spacing: 0.12em;
}

.muted { color: var(--c-fg-2); }
.accent { color: var(--c-accent); }
.light .muted { color: var(--c-fg-light-2); }

.bullet-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: var(--gap-md);
  font-family: var(--f-body);
  font-size: var(--sz-body);
  font-weight: 300;
  line-height: 1.65;
  padding-left: 0;
}

.bullet-list li {
  display: grid;
  grid-template-columns: 2em 1fr;
  gap: 0.5em;
}

.bullet-list li::before {
  content: "—";
  color: var(--c-accent);
  font-family: var(--f-mono);
}

.slide-chrome, .slide-foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.slide-chrome {
  padding-bottom: var(--gap-sm);
  border-bottom: 1px solid var(--c-border);
  margin-bottom: var(--gap-md);
}

.slide-foot {
  padding-top: var(--gap-sm);
  border-top: 1px solid var(--c-border);
  margin-top: var(--gap-md);
}

.light .slide-chrome, .light .slide-foot {
  border-color: var(--c-border-light);
}

.slide--cover .slide-chrome,
.slide--cover .slide-foot,
.slide--chapter .slide-chrome,
.slide--chapter .slide-foot,
.slide--quote .slide-chrome,
.slide--quote .slide-foot,
.slide--end .slide-chrome,
.slide--end .slide-foot {
  display: none;
}

.grove-num {
  font-family: var(--f-display);
  font-size: 18vw;
  font-weight: 400;
  line-height: 1;
  color: rgba(212, 207, 191, 0.06);
  position: absolute;
  right: var(--pad-x);
  bottom: -0.15em;
  pointer-events: none;
  user-select: none;
  letter-spacing: -0.03em;
}

.light .grove-num { color: rgba(25, 43, 27, 0.06); }
.grove-sidebar { display: none !important; }
.light .grove-sidebar { color: var(--c-fg-light-3); }

.grove-stat {
  display: flex;
  flex-direction: column;
  gap: var(--gap-sm);
  padding-bottom: var(--gap-md);
  border-bottom: 1px solid var(--c-border);
}

.grove-stat-val {
  font-family: var(--f-display);
  font-size: 4.5vw;
  font-weight: 400;
  line-height: 1;
  color: var(--c-accent);
  letter-spacing: -0.02em;
}

.grove-stat-val em { font-style: italic; }

.grove-stat-label {
  font-family: var(--f-mono);
  font-size: var(--sz-label);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--c-fg-2);
}

.light .grove-stat-label { color: var(--c-fg-light-2); }
.light .grove-stat { border-color: var(--c-border-light); }

.img-placeholder {
  background: var(--c-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--f-mono);
  font-size: var(--sz-label);
  letter-spacing: 0.1em;
  color: var(--c-fg-3);
  width: 100%;
  flex: 1;
  min-height: 30vh;
}

.light .img-placeholder {
  background: var(--c-border-light);
  color: var(--c-fg-light-3);
}

.rule {
  width: 36px;
  height: 1px;
  background: var(--c-accent);
}

.rule.full {
  width: 100%;
  background: var(--c-border);
}

.light .rule.full { background: var(--c-border-light); }

.kicker {
  font-family: var(--f-mono);
  font-size: var(--sz-label);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-accent);
}

.slide--cover {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.slide--chapter {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.chapter-num {
  font-family: var(--f-mono);
  font-size: var(--sz-label);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--c-accent);
  margin-bottom: var(--gap-md);
}

.chapter-rule {
  width: 36px;
  height: 1px;
  background: var(--c-accent);
  margin-bottom: var(--gap-md);
}

.slide--statement .statement-body {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: var(--gap-md);
}

.slide--statement .h1 {
  font-size: min(4.5vw, 7.5vh, 88px);
  line-height: 1.15;
}

.slide--split .slide-body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: calc(var(--pad-x) * 0.7);
  align-items: center;
}

.split-text {
  display: flex;
  flex-direction: column;
  gap: var(--gap-md);
}

.split-image {
  display: flex;
  flex-direction: column;
  gap: var(--gap-sm);
  height: 100%;
}

.slide--stats .slide-body {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: var(--gap-lg);
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: calc(var(--pad-x) * 0.6);
}

.slide--list .slide-body {
  display: grid;
  grid-template-columns: 2fr 3fr;
  gap: calc(var(--pad-x) * 0.8);
  align-items: center;
}

.list-head {
  display: flex;
  flex-direction: column;
  gap: var(--gap-md);
  padding-top: var(--gap-sm);
}

.slide--list .body, .slide--list .bullet-list {
  font-size: max(1.4vw, 17px);
  line-height: 1.6;
}

.slide--quote {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: calc(var(--pad-y) * 1.2) calc(var(--pad-x) * 1.1);
}

.quote-mark {
  font-family: var(--f-display);
  font-size: 8vw;
  line-height: 0.6;
  color: var(--c-accent);
  margin-bottom: var(--gap-md);
  font-weight: 400;
}

.quote-text {
  font-family: var(--f-display);
  font-size: 3.2vw;
  font-weight: 400;
  line-height: 1.35;
  letter-spacing: -0.01em;
  max-width: 75%;
  margin-bottom: var(--gap-lg);
  font-style: italic;
}

.quote-attr {
  display: flex;
  flex-direction: column;
  gap: 0.4vh;
}

.slide--compare .slide-body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  height: 100%;
}

.compare-panel {
  display: flex;
  flex-direction: column;
  gap: var(--gap-md);
  padding: var(--gap-md) 0;
}

.compare-panel.left {
  padding-right: calc(var(--pad-x) * 0.55);
  border-right: 1px solid var(--c-border);
}

.compare-panel.right {
  padding-left: calc(var(--pad-x) * 0.55);
}

.light .compare-panel.left { border-color: var(--c-border-light); }

.compare-label {
  font-family: var(--f-mono);
  font-size: var(--sz-label);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  padding-bottom: var(--gap-sm);
  border-bottom: 1px solid var(--c-border);
}

.compare-label.after { color: var(--c-accent); }
.light .compare-label { border-color: var(--c-border-light); }

.slide--end {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: var(--gap-md);
}

.slide--chart .slide-body {
  display: flex;
  flex-direction: column;
  gap: var(--gap-md);
  min-height: 0;
}

.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  flex-shrink: 0;
}

.chart-wrapper {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 0;
}

.bar-track {
  height: 30vh;
  display: flex;
  align-items: flex-end;
  gap: 4vw;
  border-left: 1px solid var(--c-border);
  padding-left: 0.5vw;
}

.light .bar-track { border-color: var(--c-border-light); }

.bar-col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-end;
  gap: 1vh;
  height: 100%;
}

.bar-fill {
  width: 100%;
  background: var(--c-fg-3);
}

.bar-fill.accent { background: var(--c-accent); }
.light .bar-fill { background: var(--c-fg-light-3); }
.light .bar-fill.accent { background: var(--c-accent); }

.bar-x-label {
  font-family: var(--f-mono);
  font-size: max(1.1vw, 13px);
  letter-spacing: 0.1em;
  color: var(--c-fg-2);
  white-space: nowrap;
  text-transform: uppercase;
}

.light .bar-x-label { color: var(--c-fg-light-2); }

.bar-val {
  font-family: var(--f-body);
  font-size: var(--sz-body);
  font-weight: 300;
  color: var(--c-fg-2);
}

.bar-val.hi {
  color: var(--c-accent);
  font-weight: 400;
}

.light .bar-val { color: var(--c-fg-light-2); }

.chart-baseline {
  height: 1px;
  background: var(--c-border);
  flex-shrink: 0;
  margin-top: 1px;
}

.light .chart-baseline { background: var(--c-border-light); }

.chart-source {
  flex-shrink: 0;
  font-family: var(--f-mono);
  font-size: var(--sz-caption);
  color: var(--c-fg-3);
  letter-spacing: 0.06em;
  margin-top: var(--gap-sm);
}

.light .chart-source { color: var(--c-fg-light-3); }
